=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO completer with edge/level interrupts.
// Implements microarchitecture.md (apb_gpio) against interface_spec.md.
module apb_gpio #(
    parameter ADDR_WIDTH = 8,
    parameter N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0 .. N-1 set: the pins that exist.
    localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

    localparam [3:0] IDX_DATA_OUT = 4'd0;
    localparam [3:0] IDX_DIR      = 4'd1;
    localparam [3:0] IDX_DATA_IN  = 4'd2;
    localparam [3:0] IDX_RISE     = 4'd3;
    localparam [3:0] IDX_FALL     = 4'd4;
    localparam [3:0] IDX_HIGH     = 4'd5;
    localparam [3:0] IDX_LOW      = 4'd6;
    localparam [3:0] IDX_ENABLE   = 4'd7;
    localparam [3:0] IDX_STATUS   = 4'd8;

    // ---------------- APB decode ----------------
    wire       access     = psel & penable;
    wire [3:0] reg_idx    = paddr[5:2];
    wire       upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
    wire       mapped     = (paddr[1:0] == 2'b00) & upper_zero & (reg_idx <= IDX_STATUS);
    wire       wr_en      = access & pwrite & mapped;
    wire       rd_en      = access & ~pwrite & mapped;

    wire [31:0] mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

    // ---------------- Registers ----------------
    reg [31:0] data_out_q, dir_q, in_q, in_prev_q;
    reg [31:0] rise_q, fall_q, high_q, low_q, ien_q, status_q;

    reg [31:0] data_out_d, dir_d, rise_d, fall_d, high_d, low_d, ien_d, status_d;

    // Input widened to 32 bits, zero above N.
    reg [31:0] in_ext;
    always @* begin
        in_ext          = 32'd0;
        in_ext[N-1:0]   = gpio_in;
    end

    // ---------------- Detection ----------------
    wire [31:0] rise_ev  = in_q & ~in_prev_q;
    wire [31:0] fall_ev  = ~in_q & in_prev_q;
    wire [31:0] detected = ((rise_ev & rise_q) | (fall_ev & fall_q)
                           | (in_q & high_q) | (~in_q & low_q)) & PINS;
    wire [31:0] clear    = (wr_en && (reg_idx == IDX_STATUS)) ? (pwdata & mask) : 32'd0;

    // ---------------- Next state ----------------
    always @* begin
        data_out_d = data_out_q;
        dir_d      = dir_q;
        rise_d     = rise_q;
        fall_d     = fall_q;
        high_d     = high_q;
        low_d      = low_q;
        ien_d      = ien_q;
        if (wr_en) begin
            case (reg_idx)
                IDX_DATA_OUT: data_out_d = (data_out_q & ~mask) | (pwdata & mask);
                IDX_DIR:      dir_d      = (dir_q      & ~mask) | (pwdata & mask);
                IDX_RISE:     rise_d     = (rise_q     & ~mask) | (pwdata & mask);
                IDX_FALL:     fall_d     = (fall_q     & ~mask) | (pwdata & mask);
                IDX_HIGH:     high_d     = (high_q     & ~mask) | (pwdata & mask);
                IDX_LOW:      low_d      = (low_q      & ~mask) | (pwdata & mask);
                IDX_ENABLE:   ien_d      = (ien_q      & ~mask) | (pwdata & mask);
                default: begin end
            endcase
        end
        // Detection ORed last: a detection beats a clear.
        status_d = (status_q & ~clear) | detected;
    end

    // ---------------- Register block (sync, active-low reset) ----------------
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
            rise_q     <= 32'd0;
            fall_q     <= 32'd0;
            high_q     <= 32'd0;
            low_q      <= 32'd0;
            ien_q      <= 32'd0;
            status_q   <= 32'd0;
        end else begin
            data_out_q <= data_out_d;
            dir_q      <= dir_d;
            in_q       <= in_ext;
            in_prev_q  <= in_q;
            rise_q     <= rise_d;
            fall_q     <= fall_d;
            high_q     <= high_d;
            low_q      <= low_d;
            ien_q      <= ien_d;
            status_q   <= status_d;
        end
    end

    // ---------------- Read mux ----------------
    reg [31:0] rdata;
    always @* begin
        rdata = 32'd0;
        if (rd_en) begin
            case (reg_idx)
                IDX_DATA_OUT: rdata = data_out_q;
                IDX_DIR:      rdata = dir_q;
                IDX_DATA_IN:  rdata = in_q;
                IDX_RISE:     rdata = rise_q;
                IDX_FALL:     rdata = fall_q;
                IDX_HIGH:     rdata = high_q;
                IDX_LOW:      rdata = low_q;
                IDX_ENABLE:   rdata = ien_q;
                IDX_STATUS:   rdata = status_q;
                default:      rdata = 32'd0;
            endcase
        end
    end

    assign prdata   = rdata;
    assign pready   = 1'b1;
    assign pslverr  = access & (~mapped | (pwrite & (reg_idx == IDX_DATA_IN)));
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & ien_q);

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
// Self-checking testbench for apb_gpio at N=8 and N=32.

// Reference model, written from interface_spec.md.
module apb_gpio_tb_model #(
    parameter N = 8
) (
    input  wire        clk,
    input  wire        rstn,
    input  wire [7:0]  addr,
    input  wire        sel,
    input  wire        en,
    input  wire        wr,
    input  wire [31:0] wdata,
    input  wire [3:0]  strb,
    input  wire [31:0] pins,
    output reg  [31:0] m_out,
    output reg  [31:0] m_dir,
    output wire        irq_o,
    output reg  [31:0] rdata_o,
    output reg         err_o
);
    localparam [31:0] MP = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    reg [31:0] m_in, m_prev, m_rise, m_fall, m_high, m_low, m_ien, m_stat;

    wire        acc   = sel & en;
    wire        legal = (addr[1:0] == 2'b00) && (addr <= 8'h20);
    wire        do_wr = acc & wr & legal;
    wire [31:0] lanes = {{8{strb[3]}}, {8{strb[2]}}, {8{strb[1]}}, {8{strb[0]}}};
    wire [31:0] wm    = lanes & MP;
    wire [31:0] det   = ((m_rise & m_in & ~m_prev) | (m_fall & m_prev & ~m_in)
                        | (m_high & m_in) | (m_low & ~m_in)) & MP;
    wire [31:0] clr   = (do_wr && (addr == 8'h20)) ? (wdata & wm) : 32'd0;

    always @(posedge clk) begin
        if (!rstn) begin
            m_out <= 32'd0; m_dir <= 32'd0; m_in <= 32'd0; m_prev <= 32'd0;
            m_rise <= 32'd0; m_fall <= 32'd0; m_high <= 32'd0; m_low <= 32'd0;
            m_ien <= 32'd0; m_stat <= 32'd0;
        end else begin
            m_in   <= pins & MP;
            m_prev <= m_in;
            if (do_wr && (addr == 8'h00)) m_out  <= (wdata & wm) | (m_out  & ~wm);
            if (do_wr && (addr == 8'h04)) m_dir  <= (wdata & wm) | (m_dir  & ~wm);
            if (do_wr && (addr == 8'h0C)) m_rise <= (wdata & wm) | (m_rise & ~wm);
            if (do_wr && (addr == 8'h10)) m_fall <= (wdata & wm) | (m_fall & ~wm);
            if (do_wr && (addr == 8'h14)) m_high <= (wdata & wm) | (m_high & ~wm);
            if (do_wr && (addr == 8'h18)) m_low  <= (wdata & wm) | (m_low  & ~wm);
            if (do_wr && (addr == 8'h1C)) m_ien  <= (wdata & wm) | (m_ien  & ~wm);
            m_stat <= det | (m_stat & ~clr);
        end
    end

    assign irq_o = |(m_stat & m_ien);

    always @* begin
        rdata_o = 32'd0;
        err_o   = 1'b0;
        if (acc) begin
            if (!legal) begin
                err_o = 1'b1;
            end else if (wr) begin
                err_o = (addr == 8'h08);
            end else begin
                case (addr)
                    8'h00: rdata_o = m_out;
                    8'h04: rdata_o = m_dir;
                    8'h08: rdata_o = m_in;
                    8'h0C: rdata_o = m_rise;
                    8'h10: rdata_o = m_fall;
                    8'h14: rdata_o = m_high;
                    8'h18: rdata_o = m_low;
                    8'h1C: rdata_o = m_ien;
                    8'h20: rdata_o = m_stat;
                    default: rdata_o = 32'd0;
                endcase
            end
        end
    end
endmodule

module apb_gpio_tb;
    localparam [7:0] A_OUT  = 8'h00;
    localparam [7:0] A_DIR  = 8'h04;
    localparam [7:0] A_IN   = 8'h08;
    localparam [7:0] A_RISE = 8'h0C;
    localparam [7:0] A_FALL = 8'h10;
    localparam [7:0] A_HIGH = 8'h14;
    localparam [7:0] A_LOW  = 8'h18;
    localparam [7:0] A_IEN  = 8'h1C;
    localparam [7:0] A_STAT = 8'h20;

    reg        pclk;
    reg        presetn;
    reg [7:0]  paddr;
    reg        psel;
    reg        penable;
    reg        pwrite;
    reg [31:0] pwdata;
    reg [3:0]  pstrb;
    reg [31:0] gpio;

    wire [31:0] prdata8, prdata32;
    wire        pready8, pready32, pslverr8, pslverr32, irq8, irq32;
    wire [7:0]  out8, oe8;
    wire [31:0] out32, oe32;

    wire [31:0] m8_out, m8_dir, m8_rd, m32_out, m32_dir, m32_rd;
    wire        m8_irq, m8_err, m32_irq, m32_err;

    integer passed   = 0;
    integer failed   = 0;
    integer cyc_pass = 0;
    integer cyc_fail = 0;
    reg     chk_en;
    reg [8*64-1:0] nonce;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8), .pready(pready8),
        .pslverr(pslverr8), .gpio_in(gpio[7:0]), .gpio_out(out8), .gpio_oe(oe8), .irq(irq8));

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
        .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32), .pready(pready32),
        .pslverr(pslverr32), .gpio_in(gpio), .gpio_out(out32), .gpio_oe(oe32), .irq(irq32));

    apb_gpio_tb_model #(.N(8)) m8 (
        .clk(pclk), .rstn(presetn), .addr(paddr), .sel(psel), .en(penable), .wr(pwrite),
        .wdata(pwdata), .strb(pstrb), .pins(gpio), .m_out(m8_out), .m_dir(m8_dir),
        .irq_o(m8_irq), .rdata_o(m8_rd), .err_o(m8_err));

    apb_gpio_tb_model #(.N(32)) m32 (
        .clk(pclk), .rstn(presetn), .addr(paddr), .sel(psel), .en(penable), .wr(pwrite),
        .wdata(pwdata), .strb(pstrb), .pins(gpio), .m_out(m32_out), .m_dir(m32_dir),
        .irq_o(m32_irq), .rdata_o(m32_rd), .err_o(m32_err));

    // Cycle-by-cycle comparison against the models (pre-edge values).
    always @(posedge pclk) begin
        if (chk_en) begin
            if ((out8 !== m8_out[7:0]) || (oe8 !== m8_dir[7:0]) || (irq8 !== m8_irq) ||
                (prdata8 !== m8_rd) || (pslverr8 !== m8_err) || (pready8 !== 1'b1)) begin
                cyc_fail = cyc_fail + 1;
                $error("N=8 model mismatch at %0t: out %h/%h oe %h/%h irq %b/%b rd %h/%h err %b/%b rdy %b",
                       $time, out8, m8_out[7:0], oe8, m8_dir[7:0], irq8, m8_irq,
                       prdata8, m8_rd, pslverr8, m8_err, pready8);
            end else begin
                cyc_pass = cyc_pass + 1;
            end
            if ((out32 !== m32_out) || (oe32 !== m32_dir) || (irq32 !== m32_irq) ||
                (prdata32 !== m32_rd) || (pslverr32 !== m32_err) || (pready32 !== 1'b1)) begin
                cyc_fail = cyc_fail + 1;
                $error("N=32 model mismatch at %0t: out %h/%h oe %h/%h irq %b/%b rd %h/%h err %b/%b rdy %b",
                       $time, out32, m32_out, oe32, m32_dir, irq32, m32_irq,
                       prdata32, m32_rd, pslverr32, m32_err, pready32);
            end else begin
                cyc_pass = cyc_pass + 1;
            end
        end
    end

    task chk(input ok, input [8*64-1:0] msg);
        begin
            if (ok) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check failed at %0t: %0s", $time, msg);
            end
        end
    endtask

    task idle(input [7:0] n);
        begin
            repeat (n) @(negedge pclk);
        end
    endtask

    task setpins(input [31:0] p);
        begin
            @(negedge pclk);
            gpio = p;
        end
    endtask

    // One APB transfer: setup, access (checked), then idle.
    task xfer(input w, input [7:0] a, input [31:0] d, input [3:0] s,
              input [31:0] x, input e, input setp, input [31:0] p);
        begin
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = w;
            paddr   = a;
            pwdata  = w ? d : 32'd0;
            pstrb   = w ? s : 4'd0;
            if (setp) gpio = p;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            if ((pready8 !== 1'b1) || (pready32 !== 1'b1)) begin
                failed = failed + 1; $error("pready not high, addr %h", a);
            end else passed = passed + 1;
            if ((pslverr8 !== e) || (pslverr32 !== e)) begin
                failed = failed + 1;
                $error("pslverr addr %h write %b: got %b/%b expected %b", a, w, pslverr8, pslverr32, e);
            end else passed = passed + 1;
            if (!w) begin
                if (prdata32 !== x) begin
                    failed = failed + 1;
                    $error("N=32 read %h: got %h expected %h", a, prdata32, x);
                end else passed = passed + 1;
                if (prdata8 !== (x & 32'h0000_00FF)) begin
                    failed = failed + 1;
                    $error("N=8 read %h: got %h expected %h", a, prdata8, x & 32'h0000_00FF);
                end else passed = passed + 1;
            end
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'd0;
            pwdata  = 32'd0;
            paddr   = 8'd0;
        end
    endtask

    task apb_wr(input [7:0] a, input [31:0] d, input [3:0] s, input e);
        begin
            xfer(1'b1, a, d, s, 32'd0, e, 1'b0, 32'd0);
        end
    endtask

    task apb_rd(input [7:0] a, input [31:0] x, input e);
        begin
            xfer(1'b0, a, 32'd0, 4'd0, x, e, 1'b0, 32'd0);
        end
    endtask

    // Write then read with no idle cycle between them.
    task b2b(input [7:0] a, input [31:0] d);
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = a; pwdata = d; pstrb = 4'hF;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk((pslverr8 === 1'b0) && (pslverr32 === 1'b0), "b2b write pslverr");
            @(negedge pclk);
            penable = 1'b0; pwrite = 1'b0; pwdata = 32'd0; pstrb = 4'd0; paddr = a;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk(prdata32 === d, "b2b read N=32");
            chk(prdata8 === (d & 32'h0000_00FF), "b2b read N=8");
            chk((pslverr8 === 1'b0) && (pslverr32 === 1'b0), "b2b read pslverr");
            @(negedge pclk);
            penable = 1'b0; paddr = A_DIR;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk(prdata32 === 32'hFF34_5678, "b2b second read DIR N=32");
            chk(prdata8 === 32'h0000_0078, "b2b second read DIR N=8");
            @(negedge pclk);
            psel = 1'b0; penable = 1'b0; paddr = 8'd0;
        end
    endtask

    task read_all_zero;
        begin
            apb_rd(A_OUT,  32'd0, 1'b0);
            apb_rd(A_DIR,  32'd0, 1'b0);
            apb_rd(A_IN,   32'd0, 1'b0);
            apb_rd(A_RISE, 32'd0, 1'b0);
            apb_rd(A_FALL, 32'd0, 1'b0);
            apb_rd(A_HIGH, 32'd0, 1'b0);
            apb_rd(A_LOW,  32'd0, 1'b0);
            apb_rd(A_IEN,  32'd0, 1'b0);
            apb_rd(A_STAT, 32'd0, 1'b0);
        end
    endtask

    task outs_zero(input [8*64-1:0] msg);
        begin
            chk((out32 === 32'd0) && (out8 === 8'd0) && (oe32 === 32'd0) && (oe8 === 8'd0) &&
                (irq32 === 1'b0) && (irq8 === 1'b0), msg);
        end
    endtask

    initial begin
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'd0;
        pwdata  = 32'd0;
        pstrb   = 4'd0;
        gpio    = 32'd0;
        chk_en  = 1'b0;

        // ---- Reset ----
        @(negedge pclk);
        chk_en = 1'b1;
        idle(2);
        outs_zero("outputs low in reset");
        presetn = 1'b1;
        outs_zero("outputs low after reset");
        read_all_zero;

        // ---- DATA_OUT with strobes ----
        apb_wr(A_OUT, 32'hA5A5_5AA5, 4'hF, 1'b0);
        apb_rd(A_OUT, 32'hA5A5_5AA5, 1'b0);
        chk((out32 === 32'hA5A5_5AA5) && (out8 === 8'hA5), "gpio_out follows DATA_OUT");
        apb_wr(A_OUT, 32'hFFFF_FFFF, 4'b0101, 1'b0);
        apb_rd(A_OUT, 32'hA5FF_5AFF, 1'b0);
        apb_wr(A_OUT, 32'h0000_0000, 4'b0000, 1'b0);
        apb_rd(A_OUT, 32'hA5FF_5AFF, 1'b0);
        apb_wr(A_OUT, 32'h0000_0000, 4'b0010, 1'b0);
        apb_rd(A_OUT, 32'hA5FF_00FF, 1'b0);
        chk((out32 === 32'hA5FF_00FF) && (out8 === 8'hFF), "gpio_out after partial writes");

        // ---- DIR ----
        apb_wr(A_DIR, 32'h1234_5678, 4'hF, 1'b0);
        apb_rd(A_DIR, 32'h1234_5678, 1'b0);
        chk((oe32 === 32'h1234_5678) && (oe8 === 8'h78), "gpio_oe follows DIR");
        apb_wr(A_DIR, 32'hFF00_0000, 4'b1000, 1'b0);
        apb_rd(A_DIR, 32'hFF34_5678, 1'b0);
        chk((oe32 === 32'hFF34_5678) && (out32 === 32'hA5FF_00FF), "DIR write leaves DATA_OUT");

        // ---- Enable registers read/write with strobes ----
        apb_wr(A_RISE, 32'h5A5A_A5A5, 4'hF, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'b1001, 1'b0);
        apb_rd(A_RISE, 32'h005A_A500, 1'b0);
        apb_wr(A_FALL, 32'h5A5A_A5A5, 4'hF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'b1001, 1'b0);
        apb_rd(A_FALL, 32'h005A_A500, 1'b0);
        apb_wr(A_HIGH, 32'h5A5A_A5A5, 4'hF, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'b1001, 1'b0);
        apb_rd(A_HIGH, 32'h005A_A500, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        // INTR_LOW with pins low: low-level detection sets status.
        apb_wr(A_LOW, 32'h5A5A_A5A5, 4'hF, 1'b0);
        apb_wr(A_LOW, 32'h0000_0000, 4'b1001, 1'b0);
        apb_rd(A_LOW, 32'h005A_A500, 1'b0);
        apb_rd(A_STAT, 32'h5A5A_A5A5, 1'b0);
        apb_wr(A_LOW, 32'h0000_0000, 4'hF, 1'b0);
        chk((irq32 === 1'b0) && (irq8 === 1'b0), "irq low with enable zero");
        apb_wr(A_IEN, 32'h5A5A_A5A5, 4'hF, 1'b0);
        chk((irq32 === 1'b1) && (irq8 === 1'b1), "irq high when enabled and pending");
        apb_wr(A_IEN, 32'h0000_0000, 4'b1001, 1'b0);
        apb_rd(A_IEN, 32'h005A_A500, 1'b0);
        chk((irq32 === 1'b1) && (irq8 === 1'b0), "irq per-instance mask");
        apb_wr(A_IEN, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk((irq32 === 1'b0) && (irq8 === 1'b0), "irq low after clear");

        // ---- DATA_IN, read only ----
        setpins(32'hDEAD_BEEF);
        idle(2);
        apb_rd(A_IN, 32'hDEAD_BEEF, 1'b0);
        apb_wr(A_IN, 32'h0000_0000, 4'hF, 1'b1);
        apb_rd(A_IN, 32'hDEAD_BEEF, 1'b0);
        // Pin change in the setup cycle is read in the access cycle.
        xfer(1'b0, A_IN, 32'd0, 4'd0, 32'h1234_5678, 1'b0, 1'b1, 32'h1234_5678);
        setpins(32'h0000_0000);
        idle(2);
        apb_rd(A_IN, 32'h0000_0000, 1'b0);

        // ---- PSLVERR policy ----
        apb_wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_rd(8'h24, 32'd0, 1'b1);
        apb_rd(8'h01, 32'd0, 1'b1);
        apb_wr(8'h02, 32'h0000_0000, 4'hF, 1'b1);
        apb_wr(8'h40, 32'h0000_0000, 4'hF, 1'b1);
        apb_wr(8'h80, 32'h0000_0000, 4'hF, 1'b1);
        apb_wr(8'hFC, 32'h0000_0000, 4'hF, 1'b1);
        apb_rd(8'hFC, 32'd0, 1'b1);
        apb_rd(8'h44, 32'd0, 1'b1);
        apb_rd(A_OUT, 32'hA5FF_00FF, 1'b0);
        apb_rd(A_STAT, 32'd0, 1'b0);

        // ---- Rising edge: fires once ----
        apb_wr(A_RISE, 32'h8000_0011, 4'hF, 1'b0);
        setpins(32'h8000_0011);
        idle(3);
        apb_rd(A_STAT, 32'h8000_0011, 1'b0);
        chk((irq32 === 1'b0) && (irq8 === 1'b0), "masked rise does not raise irq");
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- Falling edge ----
        apb_wr(A_FALL, 32'h4000_0002, 4'hF, 1'b0);
        setpins(32'hC000_0013);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        setpins(32'h8000_0011);
        idle(3);
        apb_rd(A_STAT, 32'h4000_0002, 1'b0);
        apb_wr(A_STAT, 32'h4000_0002, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- High level: sets again after a clear ----
        apb_wr(A_HIGH, 32'h2000_0004, 4'hF, 1'b0);
        setpins(32'hA000_0015);
        idle(3);
        apb_rd(A_STAT, 32'h2000_0004, 1'b0);
        apb_wr(A_STAT, 32'h2000_0004, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h2000_0004, 1'b0);
        setpins(32'h8000_0011);
        idle(3);
        apb_wr(A_STAT, 32'h2000_0004, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- Low level ----
        apb_wr(A_LOW, 32'h1000_0008, 4'hF, 1'b0);
        idle(2);
        apb_rd(A_STAT, 32'h1000_0008, 1'b0);
        setpins(32'h9000_0019);
        idle(3);
        apb_wr(A_STAT, 32'h1000_0008, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- Write-1-to-clear of some bits only ----
        setpins(32'h1000_0008);
        idle(3);
        setpins(32'h9000_0019);
        idle(3);
        apb_rd(A_STAT, 32'h8000_0011, 1'b0);
        apb_wr(A_STAT, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h8000_0011, 1'b0);
        apb_wr(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h8000_0010, 1'b0);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'b0001, 1'b0);
        apb_rd(A_STAT, 32'h8000_0000, 1'b0);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'b0110, 1'b0);
        apb_rd(A_STAT, 32'h8000_0000, 1'b0);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'b1000, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- Interrupt mask ----
        setpins(32'h9000_0009);
        idle(3);
        setpins(32'h9000_0019);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0010, 1'b0);
        chk((irq32 === 1'b0) && (irq8 === 1'b0), "pending but masked: irq low");
        apb_wr(A_IEN, 32'h0000_0010, 4'hF, 1'b0);
        chk((irq32 === 1'b1) && (irq8 === 1'b1), "unmask pending: irq high");
        apb_wr(A_IEN, 32'h0000_0020, 4'hF, 1'b0);
        chk((irq32 === 1'b0) && (irq8 === 1'b0), "other bit enabled: irq low");
        apb_rd(A_STAT, 32'h0000_0010, 1'b0);
        apb_wr(A_IEN, 32'h0000_0010, 4'hF, 1'b0);
        chk((irq32 === 1'b1) && (irq8 === 1'b1), "re-enable: irq high");
        apb_wr(A_STAT, 32'h0000_0010, 4'hF, 1'b0);
        chk((irq32 === 1'b0) && (irq8 === 1'b0), "clear: irq low");
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- A detection beats a clear on the same edge ----
        setpins(32'h9000_0009);
        idle(3);
        setpins(32'h9000_0019);
        idle(3);
        apb_rd(A_STAT, 32'h0000_0010, 1'b0);
        setpins(32'h9000_0009);
        idle(3);
        // Pin 4 rises in the setup cycle; its rise is detected on the commit edge.
        xfer(1'b1, A_STAT, 32'h0000_0010, 4'hF, 32'd0, 1'b0, 1'b1, 32'h9000_0019);
        apb_rd(A_STAT, 32'h0000_0010, 1'b0);
        chk((irq32 === 1'b1) && (irq8 === 1'b1), "detection beats clear: irq stays high");
        apb_wr(A_STAT, 32'h0000_0010, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---- Back-to-back transfers ----
        b2b(A_OUT, 32'h0F0F_0F0F);
        chk((out32 === 32'h0F0F_0F0F) && (out8 === 8'h0F), "gpio_out after b2b write");

        // ---- Reset again ----
        @(negedge pclk);
        gpio    = 32'd0;
        presetn = 1'b0;
        idle(2);
        outs_zero("outputs low in second reset");
        presetn = 1'b1;
        outs_zero("outputs low after second reset");
        read_all_zero;

        idle(2);
        chk_en = 1'b0;

        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed + cyc_pass, failed + cyc_fail);
        $finish;
    end
endmodule
